@extends('layouts.app')
@section('title', 'Bot Monitor — Jinx')
@push('head')
<style>
/* Full-width operations screen inside Jinx's existing authenticated layout. */
.bm{--neon:#6fff9b;--bright:#caffdf;--muted:#729786;--line:#1f6249;--back:#030c0b;--amber:#ffcc79;position:relative;width:calc(100vw - 48px);max-width:1880px;margin:0 0 0 50%;transform:translateX(-50%);padding:19px 22px 24px;color:#b3ebc8;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;background:radial-gradient(ellipse at 50% -10%,#103c32 0,#061911 45%,#020807 94%);border:1px solid #184d39;box-shadow:0 14px 55px #0009,inset 0 0 80px #0a251d;min-height:calc(100vh - 110px);overflow:hidden}.bm *{box-sizing:border-box}.bm:after{content:'';pointer-events:none;position:absolute;inset:0;background:repeating-linear-gradient(0deg,#0000 0,#0000 3px,#0003 4px);opacity:.32;z-index:4}.bm> *{position:relative;z-index:5}.bm-head{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap;margin-bottom:19px;border-bottom:1px solid #236345;padding-bottom:17px}.bm-eyebrow{color:#65cf94;letter-spacing:.22em;font-size:10px}.bm h1{color:#c8ffdb;font:800 clamp(20px,2.5vw,31px)/1.1 ui-monospace,monospace;margin:5px 0;text-transform:uppercase;letter-spacing:.07em;text-shadow:0 0 16px #13f46f70}.bm-intro{margin:0;color:#77a78f;font-size:11px}.bm-connect{display:flex;gap:8px;align-items:center;border:1px solid #2b845c;padding:7px 10px;color:#8bffb0;background:#082b1b;font-size:10px;letter-spacing:.08em}.bm-connect.offline{color:#ff9c9c;border-color:#803f43;background:#291518}.bm-dot{width:7px;height:7px;border-radius:50%;background:#50ff91;box-shadow:0 0 11px #50ff91;animation:bm-pulse 2s infinite}.bm-connect.offline .bm-dot{background:#ff7070;box-shadow:none}.bm-sectionhead{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:13px 0 10px;text-transform:uppercase;letter-spacing:.14em;color:#7cffaa}.bm-sectionhead h2{font-size:11px;margin:0;font-weight:750}.bm-sectionhead small{font-size:10px;color:#729786;letter-spacing:.04em;text-transform:none}.bm-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.bm-card{min-width:0;min-height:215px;border:1px solid #2a704c;background:linear-gradient(155deg,#0d291e,#07160f 77%);padding:13px;box-shadow:inset 0 0 26px #10392555}.bm-cardtop{display:flex;align-items:center;justify-content:space-between;gap:7px}.bm-identity{min-width:0;display:flex;align-items:center;gap:8px}.bm-avatar{width:30px;height:30px;flex:none;border:1px solid #358458;display:grid;place-items:center;color:#a7ffcb;background:#113c29;font-size:13px;text-shadow:0 0 10px #3cff84}.bm-avatar.dev{color:#8adfff;border-color:#397a84;background:#092e38}.bm-avatar.ivy{color:#e2aaff;border-color:#895691;background:#2b1532}.bm-avatar.pacman{color:#ffd17b;border-color:#86613b;background:#30200d}.bm-name{text-transform:uppercase;color:#e4ffec;font-size:13px;font-weight:900;letter-spacing:.09em}.bm-role{color:#79a68e;font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bm-badge{font:800 9px ui-monospace,monospace;letter-spacing:.07em;color:#8cbaa0;border:1px solid #427357;padding:4px 5px;text-transform:uppercase;white-space:nowrap}.bm-badge.working{color:#84ffb5;border-color:#3dbf75;background:#103d25}.bm-badge.waiting{color:#ffce7c;border-color:#977244}.bm-badge.offline{color:#ff9a9a;border-color:#9a4c4c}.bm-label{text-transform:uppercase;font-size:9px;letter-spacing:.14em;color:#509b70;margin:13px 0 5px}.bm-detail{color:#d5ffe0;font-size:11px;line-height:1.5;overflow-wrap:anywhere;min-height:32px}.bm-reason{color:#9cbea7;font-size:10px;line-height:1.5;overflow-wrap:anywhere;min-height:30px}.bm-decision{margin-top:9px;padding:8px;border-left:2px solid #41c676;background:#082619;font-size:10px;color:#a4ebbf;line-height:1.5;overflow-wrap:anywhere}.bm-decision:before{content:'> ';color:#7cff9e}.bm-cardfoot{margin-top:8px;font-size:9px;color:#588a6b}.bm-panel{border:1px solid #2b7951;background:#030d0b;box-shadow:inset 0 0 50px #103a1f77}.bm-toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:10px 12px;border-bottom:1px solid #28543b;background:#0b2419}.bm-toolbar input,.bm-toolbar select,.bm-toolbar button{min-width:0;background:#05150f;border:1px solid #397b53;color:#b8f8cf;border-radius:0;font:11px ui-monospace,monospace;padding:7px 9px}.bm-toolbar input{flex:1;min-width:130px}.bm-toolbar button{cursor:pointer}.bm-toolbar button:hover{background:#164229}.bm-stream{height:clamp(410px,55vh,820px);overflow:auto;scrollbar-color:#23583a #03110a;padding:4px 12px}.bm-line{display:grid;grid-template-columns:137px 112px minmax(0,1fr) 74px;gap:10px;align-items:start;border-bottom:1px solid #133322;padding:10px 6px;color:#9bffc0;font-size:11px;overflow-wrap:anywhere}.bm-line:first-child{background:linear-gradient(90deg,#0a301b,#07170f);border-left:2px solid #43db7d}.bm-line:hover{background:#102a1d}.bm-time{color:#6fa685;font-size:10px;font-variant-numeric:tabular-nums}.bm-route{font-weight:850;color:#a2ffca;white-space:nowrap}.bm-route.dev{color:#9adeee}.bm-route.ivy{color:#efbbff}.bm-route.pacman{color:#ffd58d}.bm-msgtext{color:#caf6d4;white-space:pre-wrap;line-height:1.6}.bm-kind{color:#628f71;font-size:9px;letter-spacing:.05em;text-transform:uppercase;text-align:right}.bm-kind.blocked{color:#ffb080}.bm-kind.receipt{color:#a8bba9}.bm-kind.question{color:#ffe29f}.bm-kind.completion{color:#91ffd3}.bm-typing:after{content:'▌';color:#81ffad;animation:bm-blink .7s steps(1) infinite}.bm-empty{padding:30px;color:#74a28b;text-align:center}.bm-footer{border-top:1px solid #23583b;padding:8px 12px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;color:#6da182;font-size:10px}.bm-note{font-size:10px;color:#68977d;line-height:1.6;margin-top:9px}@keyframes bm-blink{50%{opacity:0}}@keyframes bm-pulse{50%{opacity:.45;box-shadow:0 0 3px #50ff91}}@media(min-width:1600px){.bm{width:calc(100vw - 80px)}}@media(max-width:1050px){.bm{width:calc(100vw - 28px);padding:15px}.bm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:630px){.bm-grid{grid-template-columns:1fr}.bm-line{grid-template-columns:96px minmax(0,1fr) 56px;gap:6px}.bm-msgtext{grid-column:2 / 4;grid-row:auto}.bm-line .bm-kind{grid-column:3;grid-row:1}.bm-card{min-height:0}.bm-stream{height:65vh}}@media(prefers-reduced-motion:reduce){.bm-dot,.bm-typing:after{animation:none}}
</style>
@endpush
@section('content')
<main class="bm"><header class="bm-head"><div><div class="bm-eyebrow">JINX / OPERATIONS</div><h1>Bot Team Monitor</h1><p class="bm-intro">FOUR AUTONOMOUS SPECIALISTS // AUTHENTICATED MESSENGER // LIVE EVENT TELEMETRY</p></div><div id="bmConnection" class="bm-connect offline" role="status"><span class="bm-dot"></span><span id="bmConnectionText">CONNECTING</span></div></header>
<div class="bm-sectionhead"><h2>// NODE STATUS</h2><small id="bmAsOf">Waiting for source…</small></div><section class="bm-grid" id="bmCards" aria-label="Current bot activity"><article class="bm-card">Loading source-backed statuses…</article></section>
<div class="bm-sectionhead" style="margin-top:27px"><h2>// INTER-BOT TRANSMISSIONS</h2><small id="bmThreadCount">—</small></div><section class="bm-panel" aria-label="Chronological signed messenger feed"><div class="bm-toolbar"><input id="bmSearch" type="search" placeholder="Search visible messages…" aria-label="Search conversations"><select id="bmFilter" aria-label="Filter by bot"><option value="all">All bots</option><option value="zebra">Zebra</option><option value="dev">Dev</option><option value="ivy">Ivy</option><option value="pacman">Pacman</option></select><button id="bmPause" type="button">PAUSE FEED</button></div><div class="bm-stream" id="bmConversations" role="log" aria-live="off"><div class="bm-empty">Connecting to the signed conversation log…</div></div><div class="bm-footer"><span id="bmStats">—</span><span>Conversation messages are read-only</span></div></section><p class="bm-note">Decision display shows recorded activity and decision summaries, not private internal reasoning. Case-specific message bodies and sensitive references are withheld on this team-wide dashboard. A delivered message or receipt does not mean the underlying task was completed.</p></main>
@endsection
@push('scripts')
<script>
(()=>{'use strict';
const endpoint=@json(route('bot-logs.data')),by=id=>document.getElementById(id),cards=by('bmCards'),screen=by('bmConversations'),status=by('bmConnection'),statusText=by('bmConnectionText');
const roles={zebra:'GATEKEEPER',dev:'TECHNICAL',ivy:'SECRETARY',pacman:'PACKAGING'};
let data=null,paused=false,previousIds=new Set(),firstLoad=true,typing=null,renderSignature='';
const make=(tag,cls,value)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(value!==undefined)e.textContent=String(value);return e;};
const clock=t=>t&&Number.isFinite(Date.parse(t))?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date(t)):'—';
function drawCards(){if(!data)return;const fragment=document.createDocumentFragment();for(const b of data.bots){const c=make('article','bm-card'),top=make('div','bm-cardtop'),id=make('div','bm-identity'),avatar=make('div','bm-avatar '+b.role,b.role[0].toUpperCase()),nameBox=make('div');nameBox.append(make('div','bm-name',b.role),make('div','bm-role',roles[b.role]||'SPECIALIST'));id.append(avatar,nameBox);top.append(id,make('span','bm-badge '+b.state,b.state));c.append(top,make('div','bm-label',b.state==='working'?'CURRENT ACTIVITY':'CURRENT POSITION'),make('div','bm-detail',b.detail),make('div','bm-label',b.state==='idle'?'WHY IDLE':'WAITING / NEXT STEP'),make('div','bm-reason',b.reason),make('div','bm-decision',b.decision_summary),make('div','bm-cardfoot','SOURCE TIME // '+clock(b.active_since||b.waiting_since||b.last_message_at)));fragment.append(c);}cards.replaceChildren(fragment);}
function allMessages(){if(!data)return [];return data.conversations.flatMap(t=>t.messages.map(m=>({...m,thread:t.id,subject:t.subject,caseScoped:t.case_scoped}))).sort((a,b)=>Date.parse(b.time)-Date.parse(a.time)||b.id.localeCompare(a.id));}
function filtered(){const q=by('bmSearch').value.trim().toLowerCase(),role=by('bmFilter').value;return allMessages().filter(m=>(role==='all'||m.from===role||m.to===role)&&(!q||[m.from,m.to,m.kind,m.text,m.subject].join(' ').toLowerCase().includes(q)));}
function cancelTyping(){if(typing){clearInterval(typing.timer);typing=null;}screen.querySelectorAll('.bm-typing').forEach(x=>x.classList.remove('bm-typing'));}
function typeNew(row,text){const duration=window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:Math.min(1450,Math.max(350,text.length*15));if(!duration||document.hidden||paused){row.textContent=text;return;}let at=0;const tick=24;const chars=Math.max(1,Math.ceil(text.length*tick/duration));row.textContent='';row.classList.add('bm-typing');const timer=setInterval(()=>{at=Math.min(text.length,at+chars);row.textContent=text.slice(0,at);if(at>=text.length){clearInterval(timer);row.classList.remove('bm-typing');typing=null;}},tick);typing={timer};}
function drawFeed(){if(!data)return;const rows=filtered(),signature=JSON.stringify([by('bmSearch').value,by('bmFilter').value,rows.map(m=>m.id)]);if(signature===renderSignature)return;const newRows=!firstLoad?rows.filter(m=>!previousIds.has(m.id)):[];const mostRecent=newRows[0]||null;const currentScroll=screen.scrollTop;cancelTyping();const fragment=document.createDocumentFragment();for(const m of rows){const line=make('div','bm-line'),time=make('time','bm-time','['+clock(m.time)+']'),route=make('span','bm-route '+m.from,m.from.toUpperCase()+' → '+m.to.toUpperCase()+':'),message=make('span','bm-msgtext',m.text),kind=make('span','bm-kind '+m.kind,m.verified?'VERIFIED':m.kind.toUpperCase());line.dataset.messageId=m.id;line.append(time,route,message,kind);fragment.append(line);}if(!rows.length)fragment.append(make('div','bm-empty',data.conversations.length?'No signed messages match this filter.':'No signed bot messages have been recorded yet.'));screen.replaceChildren(fragment);screen.scrollTop=mostRecent?0:currentScroll;renderSignature=signature;by('bmThreadCount').textContent=rows.length+' MESSAGES // NEWEST FIRST';by('bmStats').textContent='SIGNED MESSENGER // '+rows.length+' VISIBLE MESSAGES';if(mostRecent){const active=screen.querySelector('[data-message-id="'+mostRecent.id+'"] .bm-msgtext');if(active)typeNew(active,mostRecent.text);}}
async function poll(){if(document.hidden||paused)return;try{const r=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw Error('source unavailable');const x=await r.json();if(x.schema!==2||!Array.isArray(x.bots)||!Array.isArray(x.conversations))throw Error('invalid source');data=x;const stale=x.stale||Date.now()-Date.parse(x.generated_at)>30000;status.classList.toggle('offline',stale);statusText.textContent=stale?'SIGNAL DELAYED':'● SECURE FEED ONLINE';by('bmAsOf').textContent='LAST SOURCE SYNC '+clock(x.generated_at);drawCards();drawFeed();previousIds=new Set(allMessages().map(m=>m.id));firstLoad=false;}catch{status.classList.add('offline');statusText.textContent='● SIGNAL LOST';if(!data){cards.replaceChildren(make('div','bm-empty','Source status unavailable. Retrying.'));screen.replaceChildren(make('div','bm-empty','Signed message feed unavailable. No activity is inferred.'));}}}
by('bmSearch').addEventListener('input',drawFeed);by('bmFilter').addEventListener('change',drawFeed);by('bmPause').addEventListener('click',()=>{paused=!paused;by('bmPause').textContent=paused?'RESUME LIVE FEED':'PAUSE FEED';if(paused){cancelTyping();statusText.textContent='● FEED PAUSED';}else poll();});poll();setInterval(poll,5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
</script>
@endpush
